head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50016";
scwin.processCount = "${fn:length(byApprovals)}";
scwin.obj = undefined;
scwin.frameId = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_13", attr: "__html", fn: function () { return ([String(((String((dma_pageContext.get("mode") ?? "")) === "create") ? "공시승인부서정보 등록" : "공시승인부서정보 변경"))].some(function (v) { return String(v === null ? '' : v).trim() !== ''; }) ? ("<span style=\"font-size : 12px;padding:0px 0px 3px 0px;\">제출시스템관리</span><br/> " + String(((String((dma_pageContext.get("mode") ?? "")) === "create") ? "공시승인부서정보 등록" : "공시승인부서정보 변경"))) : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_9", entity: "dlt_formApprovals", countIds: [], cells: [{ childId: "option_10", fn: function (v, i) { return String(v("depCd")); } }, { childId: "__rc0", fn: function (v, i) { return "[" + String(v("depCd")) + "] " + String(v("depNm")); } }] },
        { genId: "c_foreach_57", entity: "dlt_formApprovals", countIds: [], cells: [{ childId: "option_58", fn: function (v, i) { return String(v("depCd")); } }, { childId: "__rc4", fn: function (v, i) { return "[" + String(v("depCd")) + "] " + String(v("depNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50016' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50016' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50016.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_73_onclick
 * @description img_73 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_73_onclick = async function(e){
    try {
        await scwin.insert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50016.img_73_onclick' }); }
};

/**
 * @method
 * @name img_74_onclick
 * @description img_74 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_74_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50016.img_74_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Insert
 * @description Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/updateByformApproval.do",
        ref: "dma_InsertReq",
        target: "dlt_formApprovals=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name addByformApprovals
 * @description add Byform Approvals 처리
 * @returns {void}
 * @hidden N
 */
scwin.addByformApprovals = function () {
    const ptab = $c.util.getComponent('processTable');
    const newProcess = ptab.insertRow();
    const processCell = newProcess.insertCell();
    processCell.innerHTML = $c.util.getComponent("dma_InsertReq").get("tempApproval");
    const buttonCell = newProcess.insertCell();
    buttonCell.width = "20";
    buttonCell.height = "20";
    if (scwin.processCount > 0) {

    } else {
        ($c.util.getComponent('voidMessage') && $c.util.getComponent('voidMessage').hide ? $c.util.getComponent('voidMessage').hide() : console.warn('[sdd] hide 대상 미해결: ' + 'voidMessage'));
    }
    scwin.processCount++;
};

/**
 * @method
 * @name delByformApproval
 * @description del Byform Approval 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delByformApproval = function (obj) {
    const _tr = obj.parentNode.parentNode;
    const _tbl = _tr.parentNode;
    _tbl.removeChild(_tr);
    if (scwin.processCount > 1) {

    } else {
        ($c.util.getComponent('voidMessage') && $c.util.getComponent('voidMessage').show ? $c.util.getComponent('voidMessage').show() : console.warn('[sdd] show 대상 미해결: ' + 'voidMessage'));
    }
    scwin.processCount--;
};

/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function () {
    if (scwin.processCount > 1 && !await scwin.validation()) {
        return;
    }
    $c.util.getComponent('dma_InsertReq').set('method', "updateByformApproval");
    scwin.form_editForm.action = "/filing/updateByformApproval.do";
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validation = async function () {
    const processArray = [];
    for (let i = 0; i < $c.util.getComponent('slc_byformDepCds').length; i++) {
        const _isExit = scwin.isExit(processArray, $c.util.getComponent(["slc_byformDepCds", "slc_byformDepCds_2"][i]).getValue());
        if ($c.util.getComponent(["slc_byformDepCds", "slc_byformDepCds_2"][i]).getValue() === "") {
            await $c.win.alert("승인부서를 선택하세요.");
            return false;
        }
        if (_isExit) {
            await $c.win.alert("승인부서가 중복됩니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name isExit
 * @description is Exit 처리
 * @param {*} processArray processArray
 * @param {*} processCode processCode
 * @returns {void}
 * @hidden N
 */
scwin.isExit = function (processArray, processCode) {
    for (let i = 0; i < processArray.length; i++) {
        if (processArray[i] === processCode) {
            return true;
        }
    }
    processArray[processArray.length] = processCode;
    return false;
};
